ch(17, ['An expense is entered with vendor, category, amount and the GST on the bill, and sent for approval.', 'A different person approves; only then does the money leave the drawer.', 'Recurring templates, budgets and the month lock belong to the Owner.'],
   [('Who approves an expense entered by Reception?', 'The Manager.'), ('Why is the GST on the bill recorded?', 'To claim input tax credit.'), ('Who makes recurring templates?', 'The Owner.')])
ch(18, ['The staff register feeds the roster, the attendance and the payroll.', 'Leave is approved by someone else, and the quota is checked again at approval.', 'Payroll runs belong to the Owner; each employee sees only their own pay under My shifts & pay.'],
   [('Who may approve Kavya\'s leave?', 'Meera, the Manager; nobody approves their own leave.'), ('How many open advances can one person have?', 'One.'), ('What does an employee see under My shifts & pay?', 'Shifts, leave balance and payslip.')])
ch(19, ['The Day closing page has seven steps from Preflight to Reopen & corrections.', 'The close is blocked while overdue departures, open checks or an unclosed cash shift remain.', 'A reopened day is closed again and the reopening is recorded.'],
   [('How many steps does the day close have?', 'Seven.'), ('What blocks the close on 26 Oct in the demo?', 'Ten overdue departures.'), ('Who can reopen a closed day?', 'The Owner, with a reason.')])
ch(20, ['Reports show a period, can be exported to CSV or Excel and printed, and trace figures to source rows.', 'The Report library has search, favourites, scheduled runs and an export log.', 'The owner digest is yesterday on one page.'],
   [('What logs every export?', 'The export log.'), ('How do you keep a report at hand?', 'Add it to favourites.'), ('What is the owner digest?', 'A one-page summary of the chosen business date.')])
ch(21, ['HCC posts vouchers from the hotel\'s work; manual vouchers such as a contra or an owner drawing need approval.', 'The accountant reads the trial balance, statements, profit and loss, balance sheet, ageing, GST and TDS.', 'Year end is explained, never run in a demo.'],
   [('Who approves a manual voucher?', 'Another user, here the Owner.'), ('What does a contra do?', 'It moves money between cash and bank without income or expense.'), ('Which tab shows the money owed by companies?', 'Outstanding, the ageing.')])
ch(22, ['The compliance calendar lists the obligations of the year with due dates and an Action Center.', 'The firm profile drives which cards apply.', 'The assistant answers from the hotel\'s own data and flags anomalies.'],
   [('What does the Action Center show?', 'Overdue and due-soon obligations with the amount payable.'), ('Does the assistant use the internet?', 'No. It uses the hotel\'s own data.'), ('What does Go there do?', 'It opens the screen behind a flag.')])
ch(23, ['Users get roles; custom roles start from a base role and are adjusted per sub-function.', 'A sub-function can be switched off and on; the data is kept.', 'Master configuration, backups, system health, legacy import and the roadmap are the Owner\'s and Tech admin\'s pages.'],
   [('Is data lost when a sub-function is switched off?', 'No. The data is kept.'), ('Who changes money and tax settings?', 'The Owner only.'), ('What does a dry run of the legacy import do?', 'It reports what would be loaded without changing anything.')])
ch(24, ['F2, F3, F4, F6, F7, F8, F10 and Alt+B open the main screens; Alt+/ lists the keys you may use.', 'Ctrl K searches pages and actions from anywhere.', 'Sign out when you leave the desk.'],
   [('Which key opens the Room board?', 'F6.'), ('Which keys list the shortcuts?', 'Alt and the slash key.'), ('Why sign out when leaving the desk?', 'Everything is recorded under the signed-in name.')])

content = {'recap': R,
           'fkeys': [['F2', 'New booking'], ['F3', 'Arrivals & check-in'], ['F4', 'In-house stays'], ['F6', 'Room board'], ['F7', 'Guests & folios'], ['F8', 'Check-out'], ['F9', 'Rate / guest change'], ['F10', 'Cashier shift'], ['Alt+B', 'Counter bill'], ['Alt+/', 'Keyboard shortcuts'], ['Ctrl K', 'Search pages and actions']],
           'menumap': [['Front Desk', 'Room board, calendar, reservations, guests, room keys, arrivals & check-in'], ['Cash & Billing', 'Folios, counter bills, cashier shift, cash book, restaurant, expenses'],
                       ['Housekeeping & Maintenance', 'Housekeeping board, maintenance work orders, shift handover'], ['Guests & Services', 'In-house stays, guest services, messages, document capture'],
                       ['Customers', 'Customer 360 profiles and stay history'], ['Revenue & Sales', 'Tariff and yield, tariff card, groups, OTA, booking site, hall booking'],
                       ['Stock & Purchasing', 'Linen, stock, purchases, assets'], ['People & Payroll', 'Staff, leave, payroll, my shifts and pay'],
                       ['Accounts & Reports', 'Day closing, reports, report hub, accounting, compliance, assistant'], ['Admin & Setup', 'Users and roles, settings, masters, approvals, backup, system health']],
           'reference_lines': {'keyboard': ['Ctrl K - search pages and actions', 'Esc - close a dialog or the search box', 'F2 new booking, F3 arrivals, F6 room board, F7 folios, F10 cashier'],
                               'passwords': ['Demo users: choose a name with Preview as. There are no passwords in the training build.'],
                               'keyboard_narration': 'Control K opens the search box, Escape closes a dialog. F2 is a new booking, F3 arrivals, F6 the room board, F7 folios and F10 the cashier shift.',
                               'passwords_narration': 'The training build has demo users that you choose by name. There are no passwords.'}}
json.dump(content, open(os.path.join(HERE, 'content.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('recaps', len(R))
